<?php
namespace AmitShaw\FCB;
defined('ABSPATH') || exit;
$enabled=array_filter($live['channels'],function($ch){return $ch['enabled'];});
$summary=$live['inbox'] ? Store::query() : ['total'=>0,'rows'=>[]];
$new=$live['inbox'] ? Store::query('','new')['total'] : 0;
$contacted=$live['inbox'] ? Store::query('','contacted')['total'] : 0;
?>
<div class="fcb-page-heading"><div><span class="fcb-eyebrow"><?php esc_html_e('YOUR CONTACT HUB',self::DOMAIN); ?></span><h1><?php esc_html_e('A conversation starts here.',self::DOMAIN); ?></h1><p><?php esc_html_e('Make it easy for the right people to reach you.',self::DOMAIN); ?></p></div><span class="fcb-status <?php echo $live['enabled'] ? 'is-live' : ''; ?>"><i></i><?php echo $live['enabled'] ? esc_html__('Widget is live',self::DOMAIN) : esc_html__('Widget is off',self::DOMAIN); ?></span></div>
<div class="fcb-overview-grid">
    <section class="fcb-welcome"><div><span class="fcb-eyebrow"><?php esc_html_e('A SMALL WIDGET. A WARMER WELCOME.',self::DOMAIN); ?></span><h2><?php esc_html_e('Be one click closer to your customers.',self::DOMAIN); ?></h2><p><?php esc_html_e('Calls, messages, and callback requests — in a contact experience that feels like you.',self::DOMAIN); ?></p><a class="fcb-button fcb-button-primary" href="<?php echo esc_url(admin_url('admin.php?page=fcb-setup')); ?>"><?php echo empty($enabled) ? esc_html__('Set up your contact buttons',self::DOMAIN) : esc_html__('Resume Easy Setup',self::DOMAIN); ?> <span>↗</span></a><a class="fcb-text-link" href="<?php echo esc_url(admin_url('admin.php?page=fcb-design')); ?>"><?php esc_html_e('Open Design Studio',self::DOMAIN); ?> →</a></div><div class="fcb-hero-art" aria-hidden="true"><span class="fcb-art-bubble"><?php esc_html_e('Hello! How can we help?',self::DOMAIN); ?></span><span class="fcb-art-orbit fcb-art-whatsapp"><?php echo Widget::icon('whatsapp'); ?></span><span class="fcb-art-orbit fcb-art-call"><?php echo Widget::icon('call'); ?></span><span class="fcb-art-orbit fcb-art-email"><?php echo Widget::icon('email'); ?></span><div class="fcb-art-label"><i></i><?php esc_html_e('Let’s talk',self::DOMAIN); ?></div></div></section>
    <section class="fcb-card-admin fcb-published"><span class="fcb-eyebrow"><?php esc_html_e('PUBLISHED WIDGET',self::DOMAIN); ?></span><h2><?php esc_html_e('Ready when you are.',self::DOMAIN); ?></h2><p><?php echo $enabled ? esc_html__('Your enabled contact methods:',self::DOMAIN) : esc_html__('Complete Easy Setup to publish your first contact button.',self::DOMAIN); ?></p><div class="fcb-channel-chips"><?php foreach ($enabled as $key=>$ch) { echo '<span>'.Widget::icon($key).esc_html($ch['label']).'</span>'; } ?></div><button type="button" class="fcb-button fcb-button-light" data-admin-action="toggle"><?php echo $live['enabled'] ? esc_html__('Disable widget',self::DOMAIN) : esc_html__('Enable widget',self::DOMAIN); ?></button><a class="fcb-text-link" href="<?php echo esc_url(home_url('/')); ?>" target="_blank" rel="noopener"><?php esc_html_e('View your site',self::DOMAIN); ?> ↗</a></section>
</div>
<div class="fcb-stats">
<section class="fcb-stat"><span><?php esc_html_e('Contact methods',self::DOMAIN); ?></span><strong><?php echo count($enabled); ?><small>/ 7</small></strong><p><?php esc_html_e('Configured in your published widget',self::DOMAIN); ?></p></section>
<section class="fcb-stat"><span><?php esc_html_e('New enquiries',self::DOMAIN); ?></span><strong><?php echo $live['inbox'] ? (int)$new : '—'; ?></strong><p><?php echo $live['inbox'] ? esc_html__('Submitted requests awaiting first follow-up',self::DOMAIN) : esc_html__('Enable the private inbox to keep requests',self::DOMAIN); ?></p></section>
<section class="fcb-stat"><span><?php esc_html_e('Still unresolved',self::DOMAIN); ?></span><strong><?php echo $live['inbox'] ? (int)($new+$contacted) : '—'; ?></strong><p><?php esc_html_e('New and Contacted requests in your inbox',self::DOMAIN); ?></p></section>
</div>
<div class="fcb-bottom-grid"><section class="fcb-card-admin"><div class="fcb-section-heading"><h2><?php esc_html_e('Your next conversation',self::DOMAIN); ?></h2><a href="<?php echo esc_url(admin_url('admin.php?page=fcb-inbox')); ?>"><?php esc_html_e('Open inbox',self::DOMAIN); ?> →</a></div><?php if (!$summary['rows']) : ?><div class="fcb-empty"><?php echo Widget::icon('chat'); ?><h3><?php esc_html_e('A little quiet, for now.',self::DOMAIN); ?></h3><p><?php esc_html_e('Real callback requests will appear here when local inbox storage is enabled. Button clicks do not identify customers.',self::DOMAIN); ?></p></div><?php else : ?><div class="fcb-recent"><?php foreach (array_slice($summary['rows'],0,4) as $r) { echo '<div><strong>'.esc_html($r['name'] ?: $r['contact']).'</strong><span>'.esc_html($r['status']).'</span><small>'.esc_html(get_date_from_gmt($r['created_at'],get_option('date_format').' '.get_option('time_format'))).'</small></div>'; } ?></div><?php endif; ?></section>
<section class="fcb-card-admin"><span class="fcb-eyebrow"><?php esc_html_e('GOOD TO KNOW',self::DOMAIN); ?></span><h2><?php esc_html_e('Small footprint. Clear expectations.',self::DOMAIN); ?></h2><ul class="fcb-checklist"><li><?php esc_html_e('Contact links open the selected service.',self::DOMAIN); ?></li><li><?php esc_html_e('A click cannot confirm a connected call or a sent message.',self::DOMAIN); ?></li><li><?php esc_html_e('Notifications use your WordPress mail transport.',self::DOMAIN); ?></li><li><?php esc_html_e('Contact Insights and weekly reports are optional. Configure them in Insights.',self::DOMAIN); ?></li></ul><a href="<?php echo esc_url(admin_url('admin.php?page=fcb-advanced')); ?>"><?php esc_html_e('Review privacy & notification settings',self::DOMAIN); ?> →</a></section></div>
